def transform_orth(grid):
    out=[row[:] for row in grid]; bg=grid[0][0]
    pts={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v!=bg}
    # Connect consecutive markers in each row and column.
    for r in range(len(grid)):
        cols=sorted(c for rr,c in pts if rr==r)
        for a,b in zip(cols,cols[1:]):
            for c in range(a+1,b): out[r][c]=3
    for c in range(len(grid[0])):
        rows=sorted(r for r,cc in pts if cc==c)
        for a,b in zip(rows,rows[1:]):
            for r in range(a+1,b): out[r][c]=3
    return out
